package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Actual original acceptance and shared short writer; no model or production data. */
class OwnerAdHocIntentCancelTest {
 OwnerAdHocCreationTest c;JdbcOwnerAdHocCreation.Accepted accepted;DataSourceTransactionManager tx;TimeZone previous;
 OwnerAdHocCreationTest fixtureSource(){return new OwnerAdHocCreationTest();}boolean mysql(){return false;}
 @BeforeEach void setup(){previous=TimeZone.getDefault();if(!mysql())TimeZone.setDefault(TimeZone.getTimeZone("UTC"));c=fixtureSource();c.setup();if(!mysql()){var source=(org.h2.jdbcx.JdbcDataSource)c.f.source;source.setURL(source.getURL()+";TIME ZONE=UTC");}if(!mysql())c.f.jdbc.execute("CREATE ALIAS UNHEX FOR 'com.lianxibu.site.service.jobs.ResultJdbcStoreTest.unhex'");tx=new DataSourceTransactionManager(c.f.source);for(String column:List.of("result_hash BINARY(32)","report_mode VARCHAR(32)"))c.f.jdbc.execute("ALTER TABLE jobs ADD "+column);accepted=c.first();}
 @AfterEach void restore(){TimeZone.setDefault(previous);}
 OwnerAdHocIntentCancelService service(PlatformTransactionManager manager){return new OwnerAdHocIntentCancelService(c.f.source,manager,new SharedWriteExecutor(new JdbcSharedWriteEntry(c.f.source),manager,()->25,n->{}),c.f.clock);}
 JdbcOwnerJobCancellation.Cancelled cancel(String key,long revision){return service(tx).cancelIfIntent(c.owner,accepted.command().intentId(),revision,"Fictional intent cancellation",key);}
 GenerationFlowService.Frozen prepare(){return new OwnerAdHocPreparationService(c.f.source,c.accepted,c.f.writes,tx,c.f.clock,()->c.allowed).prepare(accepted.actionKey());}
 @Test void OriginalUnpreparedIntentCancelsOnceAndQuestionIsPreservedWithoutSlotOrBudgetWork(){var before=new JdbcWorkerState(c.f.source).slot();int freezes=c.freezes;c.allowed=false;var result=cancel("fictional-intent-cancel",0);assertEquals(accepted.command().intentId(),result.rootId());assertEquals("cancelled",result.state());assertEquals(1,result.revision());assertEquals(1,c.f.count("target_type='job_intent_cancel'"));assertEquals(0,c.f.count("record_kind IN ('logical_task','ai_attempt','snapshot_part')"));assertEquals(before,new JdbcWorkerState(c.f.source).slot());assertEquals(freezes,c.freezes);assertEquals(accepted.json(),c.first().json());var reads=new TransactionTemplate(tx);reads.setReadOnly(true);assertEquals(accepted.command().prompt(),reads.execute(s->c.accepted.originalIntent(accepted.command().intentId()).command().prompt()));assertThrows(RuntimeException.class,this::prepare);assertEquals(0,c.f.count("record_kind='logical_task'"));}
 @Test void ExactCommittedReceiptSurvivesRestartAndLaterEligibilityChanges(){var original=cancel("fictional-intent-cancel",0);c.f.jdbc.update("UPDATE jobs SET revision=9,state='superseded' WHERE id=?",accepted.command().intentId());assertEquals(original,cancel("fictional-intent-cancel",0));assertEquals(1,c.f.count("target_type='job_intent_cancel'"));for(Runnable change:List.<Runnable>of(()->cancel("fictional-intent-cancel",1),()->service(tx).cancelIfIntent(c.owner,accepted.command().intentId(),0,"Fictional changed reason","fictional-intent-cancel"),()->service(tx).cancelIfIntent(new IdentityService.Actor("fictional-other-owner","owner"),accepted.command().intentId(),0,"Fictional intent cancellation","fictional-intent-cancel"),()->service(tx).cancelIfIntent(c.owner,"fictional-other-intent",0,"Fictional intent cancellation","fictional-intent-cancel")))assertEquals("identity_conflict",assertThrows(JdbcOwnerJobCancellation.Rejected.class,change::run).getMessage());}
 @Test void NewKeyMayConfirmAlreadyCancelledWithoutAnotherRevisionOrRecreatingSameQuestion(){var first=cancel("fictional-intent-cancel",0);var again=cancel("fictional-intent-cancel-again",1);assertEquals(1,again.revision());assertNotEquals(first.operationRef(),again.operationRef());assertEquals(2,c.f.count("target_type='job_intent_cancel'"));assertEquals("input_unchanged",assertThrows(JdbcOwnerAdHocCreation.Rejected.class,()->c.create.create(c.owner,"fictional-new-target",accepted.command().prompt(),"Fictional duplicate reason","fictional-new-create")).getMessage());assertEquals(0,c.f.count("record_kind='logical_task'"));}
 @Test void PreparedIntentIsFrozenButItsOriginalRootRemainsWithTheSameThreeCallBudget(){var original=prepare();assertEquals("run_frozen",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel("fictional-too-late",0)).getMessage());assertEquals(0,c.f.count("target_type='job_intent_cancel'"));assertEquals(1,c.f.count("record_kind='logical_task' AND call_count=0 AND max_attempts=3"));assertNull(service(tx).cancelIfIntent(c.owner,original.ownerId(),0,"Fictional root delegation","fictional-root-cancel"));var roots=new OwnerJobCancelService(c.f.writes,new JdbcOwnerJobCancellation(c.f.source),c.f.clock);assertEquals("cancelled",roots.cancel(c.owner,original.ownerId(),0,"Fictional root cancellation","fictional-root-cancel").state());}
 @Test void NativeOrphanRootCannotBeHiddenAsAnUnpreparedIntent(){prepare();c.f.jdbc.update("UPDATE jobs SET state='waiting_input',input_state='waiting_input',snapshot_owner_id=NULL,input_cutoff_at=NULL WHERE id=?",accepted.command().intentId());c.f.jdbc.update("DELETE FROM jobs WHERE target_type='generation_prepare'");assertEquals("run_frozen",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel("fictional-orphan-cancel",0)).getMessage());assertEquals(0,c.f.count("target_type='job_intent_cancel'"));}
 @Test void StaleRevisionAndDamagedOriginalAcceptanceNeverWrite(){assertEquals("revision_conflict",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel("fictional-stale",1)).getMessage());c.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='owner_ad_hoc_create'",new byte[32]);assertThrows(IllegalStateException.class,()->cancel("fictional-damaged-original",0));assertEquals(0,c.f.count("target_type='job_intent_cancel'"));assertEquals("waiting_input",c.f.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,accepted.command().intentId()));}
 @Test void ReceiptFailureRollsBackAndRealLostCommitAcknowledgementReplaysOriginal(){c.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_intent_cancel_refused CHECK(COALESCE(target_type,'')<>'job_intent_cancel')");assertThrows(RuntimeException.class,()->cancel("fictional-intent-cancel",0));assertEquals("waiting_input",c.f.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,accepted.command().intentId()));assertEquals(0,c.f.count("target_type='job_intent_cancel'"));c.f.jdbc.execute(mysql()?"ALTER TABLE jobs DROP CHECK fictional_intent_cancel_refused":"ALTER TABLE jobs DROP CONSTRAINT fictional_intent_cancel_refused");var manager=new PlatformTransactionManager(){boolean once=true;public TransactionStatus getTransaction(TransactionDefinition d){return tx.getTransaction(d);}public void rollback(TransactionStatus s){tx.rollback(s);}public void commit(TransactionStatus s){boolean writer=!TransactionSynchronizationManager.isCurrentTransactionReadOnly();tx.commit(s);if(writer&&once){once=false;throw new TransactionSystemException("Fictional lost acknowledgement");}}};var result=service(manager).cancelIfIntent(c.owner,accepted.command().intentId(),0,"Fictional intent cancellation","fictional-intent-cancel");assertEquals(result,cancel("fictional-intent-cancel",0));assertEquals(1,result.revision());}
 @Test void DamagedReceiptAndOtherNativeRecordKindsCannotCreateCancellation(){cancel("fictional-intent-cancel",0);c.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='job_intent_cancel'",new byte[32]);assertThrows(IllegalStateException.class,()->cancel("fictional-intent-cancel",0));assertNull(service(tx).cancelIfIntent(c.owner,"fictional-absent",0,"Fictional absent","fictional-absent-key"));assertNull(service(tx).cancelIfIntent(c.owner,c.f.jdbc.queryForObject("SELECT id FROM jobs WHERE target_type='owner_ad_hoc_create'",String.class),0,"Fictional receipt delegation","fictional-receipt-key"));assertEquals(1,c.f.count("target_type='job_intent_cancel'"));}
 @Test void OwnerAuthorizationAndConstructionHaveZeroDatabaseWorkAndOuterTransactionCannotWrite(){var source=org.mockito.Mockito.mock(javax.sql.DataSource.class);var manager=new DataSourceTransactionManager(source);var service=new OwnerAdHocIntentCancelService(source,manager,new SharedWriteExecutor(new JdbcSharedWriteEntry(source),manager),c.f.clock);org.mockito.Mockito.verifyNoInteractions(source);assertThrows(IdentityService.Rejected.class,()->service.cancelIfIntent(null,null,0,null,null));assertThrows(IdentityService.Rejected.class,()->service.cancelIfIntent(new IdentityService.Actor("fictional-member","member"),null,0,null,null));assertThrows(IllegalArgumentException.class,()->service.cancelIfIntent(c.owner,"\n",0,null,null));org.mockito.Mockito.verifyNoInteractions(source);var reads=new TransactionTemplate(tx);reads.setReadOnly(true);assertThrows(IllegalStateException.class,()->reads.execute(s->cancel("fictional-outer",0)));assertEquals(0,c.f.count("target_type='job_intent_cancel'"));}
 @Test void CancelAndPrepareCompeteAtTheSameActualSharedWriterAndCannotReviveCancelledIntent()throws Exception{var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var cancellation=pool.submit(()->{start.await();try{return cancel("fictional-competing-cancel",0);}catch(RuntimeException refused){return null;}});var preparation=pool.submit(()->{start.await();try{return prepare();}catch(RuntimeException refused){return null;}});start.countDown();var cancelled=cancellation.get(10,TimeUnit.SECONDS);var prepared=preparation.get(10,TimeUnit.SECONDS);assertNotEquals(cancelled==null,prepared==null);if(cancelled!=null){assertEquals("cancelled",c.f.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,accepted.command().intentId()));assertEquals(0,c.f.count("record_kind='logical_task' OR record_kind='ai_attempt'"));assertThrows(RuntimeException.class,this::prepare);}else{assertEquals(1,c.f.count("record_kind='logical_task' AND call_count=0 AND max_attempts=3"));assertEquals(0,c.f.count("target_type='job_intent_cancel'"));}}}
}
